import { AuthType, EmbedConfig } from '@thoughtspot/visual-embed-sdk';

/** ThoughtSpot data model (worksheet) GUID for Search / Spotter embeds */
export const THOUGHTSPOT_MODEL_ID = '3a3782f6-e861-4e9d-9e0b-c69c2ad5183c';

/** Liveboard GUID for LiveboardEmbed */
export const THOUGHTSPOT_LIVEBOARD_ID = 'eaf56a2b-d07e-4037-8abe-b0e46c55030a';

/** Cluster URL */
export const thoughtSpotHost = 'https://se-thoughtspot-cloud.thoughtspot.cloud';

/**
 * Build SDK init config using Basic auth.
 */
export function buildThoughtSpotEmbedConfig(): EmbedConfig {
  return {
    thoughtSpotHost,
    authType: AuthType.Basic,
    username: 'katie.matkin@thoughtspot.com',
    password: 'Sheffield.1!',
    featureFlags: {
      enable2ColumnLayout: true,
      isLiveboardStylingAndGroupingEnabled: true,
    },
    customizations: {
      content: {
        strings: {
          'Spotter': 'JETT AI',
        },
      },
    },
  };
}
